import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Story","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/story.md","filePath":"03-developer/models/story.md"}`),a={name:`03-developer/models/story.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="story" tabindex="-1">Story <a class="header-anchor" href="#story" aria-label="Permalink to “Story”">​</a></h1><p>The <code>Story</code> model is used to manage display stories, similar to Instagram Stories. Each record includes a title, description, preview image, original file, publication status, and display order.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique story ID</td></tr><tr><td><code>title</code></td><td>VARCHAR(255)</td><td>No</td><td>Story title; translatable</td></tr><tr><td><code>slug</code></td><td>VARCHAR(255), unique</td><td>No</td><td>Unique text identifier for the story, used in the URL</td></tr><tr><td><code>description</code></td><td>LONGTEXT</td><td>No</td><td>Story description</td></tr><tr><td><code>image</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Name or ID of the story preview image file</td></tr><tr><td><code>file</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Path to the original story file, including an image or video</td></tr><tr><td><code>ext</code></td><td>VARCHAR(255)</td><td>Yes</td><td>File extension</td></tr><tr><td><code>likes</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Number of likes on the story; defaults to <code>0</code></td></tr><tr><td><code>status</code></td><td>TINYINT(1)</td><td>No</td><td>Publication status; <code>0</code> for draft (<code>Draft</code>) and <code>1</code> for published (<code>Published</code>)</td></tr><tr><td><code>sort</code></td><td>INT UNSIGNED</td><td>No</td><td>Story display order; defaults to <code>0</code></td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Story creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last story update</td></tr><tr><td><code>deleted_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Story soft deletion time</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="translatable" tabindex="-1"><code>$translatable</code> <a class="header-anchor" href="#translatable" aria-label="Permalink to “$translatable”">​</a></h3><p>The <code>title</code> field is defined as translatable, allowing the story title to be stored and displayed in different languages.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getroutekeyname" tabindex="-1"><code>getRouteKeyName()</code> <a class="header-anchor" href="#getroutekeyname" aria-label="Permalink to “getRouteKeyName()”">​</a></h3><p>Uses the <code>slug</code> field instead of <code>id</code> for Route Model Binding.</p><h3 id="imgurl" tabindex="-1"><code>imgUrl()</code> <a class="header-anchor" href="#imgurl" aria-label="Permalink to “imgUrl()”">​</a></h3><p>Returns the URL of the optimized story image. If no image is available, the site logo is used as a fallback.</p><h3 id="imgoriginalurl" tabindex="-1"><code>imgOriginalUrl()</code> <a class="header-anchor" href="#imgoriginalurl" aria-label="Permalink to “imgOriginalUrl()”">​</a></h3><p>Returns the URL of the original story image. If no image is available, the site logo is used as a fallback.</p><h3 id="url" tabindex="-1"><code>url()</code> <a class="header-anchor" href="#url" aria-label="Permalink to “url()”">​</a></h3><p>Returns the URL of the original story file, whether an image or video. If no file is available, the site logo is used as a fallback.</p><h3 id="commentcount" tabindex="-1"><code>commentCount()</code> <a class="header-anchor" href="#commentcount" aria-label="Permalink to “commentCount()”">​</a></h3><p>Returns the number of comments on the story. This method is not currently implemented and returns the fixed value <code>15</code>.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>The <code>slug</code> field has a unique index, so its value cannot be duplicated in the table.</li><li>The <code>image</code> field is used for the preview image, and the <code>file</code> field is used for the original story file.</li><li>The optimized preview image is stored in <code>optimized/stories/</code>, and the original image is stored in <code>stories/</code>.</li><li>The <code>status</code> field specifies whether the story is a draft or published; displaying published stories depends on the application logic.</li><li>The <code>sort</code> field is used to determine the display order of stories; the final order depends on how queries sort the results.</li><li>The <code>likes</code> and <code>sort</code> fields default to <code>0</code>.</li><li>The <code>deleted_at</code> field is intended to record the time of soft deletion; whether Soft Deletes is enabled depends on the model configuration.</li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};